"
    Method checking all objects. The pkgutil-based method in
    `test_all_modules_are_expected` does not catch imports into a namespace,
    only filenames.  So this test is more thorough, and checks this like:

        import .lib.scimath as emath

    To check if something in a module is (effectively) public, one can check if
    there's anything in that namespace that's a public function/object but is
    not exposed in a higher-level namespace.  For example for a `numpy.lib`
    submodule::

        mod = np.lib.mixins
        for obj in mod.__all__:
            if obj in np.__all__:
                continue
            elif obj in np.lib.__all__:
                continue

            else:
                print(obj)

    "

def find_unexpected_members(mod_name):
    members = []
    module = importlib.import_module(mod_name)
    if hasattr(module, '__all__'):
        objnames = module.__all__
    else:
        objnames = dir(module)
    for objname in objnames:
        if not objname.startswith('_'):
            fullobjname = mod_name + '.' + objname
            if isinstance(getattr(module, objname), types.ModuleType):
                if is_unexpected(fullobjname):
                    if fullobjname not in SKIP_LIST_2:
                        members.append(fullobjname)
    return members
unexpected_members = find_unexpected_members('numpy')
for modname in PUBLIC_MODULES:
    unexpected_members.extend(find_unexpected_members(modname))
if unexpected_members:
    raise AssertionError(f'Found unexpected object(s) that look like modules: {unexpected_members}')

'\n    Checks if `dir(np)` and `np.__all__` are consistent and return\n    the same content, excluding exceptions and private members.\n    '

def _remove_private_members(member_set):
    return {m for m in member_set if not m.startswith('_')}

def _remove_exceptions(member_set):
    return member_set.difference({'bool'})
all_members = _remove_private_members(np.__all__)
all_members = _remove_exceptions(all_members)
dir_members = _remove_private_members(np.__dir__())
dir_members = _remove_exceptions(dir_members)
assert all_members == dir_members, f'Members that break symmetry: {all_members.symmetric_difference(dir_members)}'

'\n    Check that all "semi-public" members of `numpy._core` are also accessible\n    from `numpy.core` shims.\n    '
import numpy.core as core
for member_name in dir(np._core):
    if member_name.startswith('_') or member_name in ['tests', 'strings'] or f'numpy.{member_name}' in PUBLIC_ALIASED_MODULES:
        continue
    member = getattr(np._core, member_name)
    if inspect.ismodule(member) and member.__spec__ and (member.__spec__.origin is not None):
        submodule = member
        submodule_name = member_name
        for submodule_member_name in dir(submodule):
            if submodule_member_name.startswith('__'):
                continue
            submodule_member = getattr(submodule, submodule_member_name)
            core_submodule = __import__(f'numpy.core.{submodule_name}', fromlist=[submodule_member_name])
            assert submodule_member is getattr(core_submodule, submodule_member_name)
    else:
        assert member is getattr(core, member_name)

modules_queue = [np]
visited_modules = {np}
visited_functions = set()
incorrect_entries = []
while len(modules_queue) > 0:
    module = modules_queue.pop()
    for member_name in dir(module):
        member = getattr(module, member_name)
        if inspect.ismodule(member) and 'numpy' in member.__name__ and (not member_name.startswith('_')) and ('numpy._core' not in member.__name__) and (member_name not in ['char', 'core', 'f2py', 'ma', 'lapack_lite', 'mrecords', 'testing', 'tests', 'polynomial', 'typing', 'mtrand', 'bit_generator']) and (member not in visited_modules):
            modules_queue.append(member)
            visited_modules.add(member)
        elif not inspect.ismodule(member) and hasattr(member, '__name__') and (not member.__name__.startswith('_')) and (member.__module__ != module.__name__) and (member not in visited_functions):
            if member.__name__ in ('add', 'equal', 'not_equal', 'greater', 'greater_equal', 'less', 'less_equal') and module.__name__ == 'numpy.strings':
                continue
            if member.__name__ == 'recarray' and module.__name__ == 'numpy' or (member.__name__ == 'record' and module.__name__ == 'numpy.rec'):
                continue
            if member.__name__ in ('c_long', 'c_longlong') and module.__name__ == 'numpy.ctypeslib':
                continue
            if member.__name__ in ('BitGenerator', 'Generator', 'MT19937', 'PCG64', 'PCG64DXSM', 'Philox', 'RandomState', 'SFC64', 'SeedSequence'):
                continue
            incorrect_entries.append({'Func': member.__name__, 'actual': member.__module__, 'expected': module.__name__})
            visited_functions.add(member)
if incorrect_entries:
    assert len(incorrect_entries) == 0, incorrect_entries

