def get_out_axis_size(a, b, axis):
    if axis is None:
        if a.ndim == 1:
            return (a.size, False)
        else:
            return ('skip', False)
    else:
        return (a.shape[axis], False)

def do_reduceat(a, out, axis):
    if axis is None:
        size = len(a)
        step = size // len(out)
    else:
        size = a.shape[axis]
        step = a.shape[axis] // out.shape[axis]
    idx = np.arange(0, size, step)
    return np.add.reduceat(a, idx, out=out, axis=axis)
